response:
**Gates before launch**

I run four gates, and any failure halts the round and gets reported to you. First, `git log` and `git status` confirm that spe/predictions/r04.yaml and spe/plans/r04.md are committed and unchanged. Second, the grader selftest runs `python3 -I spe/evals/graders/grade.py --selftest`. The oracle (answers.json fed back as trials) must score 100%. An empty trial file and a deliberately wrong file must both fail. Third, the control regrade runs grade.py on the round 3 trial files in spe/evals/runs/r03/. Its numbers must match the r03 Measured column in spe/prediction-log.md exactly. A mismatch counts as a grader bug and halts the round. Fourth, I run `node --check` and then a dry run with `{dryRun: true}`. The dry run covers 3 cells with 2 trials each and writes to spe/evals/runs/r04-dry, which does not count toward results. In the dry run, every trial must return valid output, grade.py must grade every trial ID, the judge must score every reply, and the peek scan must find every trial transcript. The dry run also measures the real cost of each call type. I pass those costs as `args.estUsd` with a 25% margin. If the projected spend is over $40, I halt and ask you. I do not shrink the plan on my own. After the gates pass, I commit `SPE r04 evaluate (harness)` and launch.

**Defaults I chose:**
- Trials follow round 3's pattern. A trial agent plays the support agent, working from the config text and ticket in its prompt.
- `args.trialModel` is whatever model r03-workflow.js used, so the model under test stays the same.
- The config and ticket files are spe/evals/configs/B.md, spe/evals/configs/C2.md and spe/evals/tasks/tickets.json.
- grade.py takes `--answers`, `--trials`, `--json` and `--selftest`.
- A split cell gets up to 5 extra trials, with 60 extra trials in total. Only the base 5 trials per cell are compared to the prediction.
- The `estUsd` values in the script are estimates until the dry run replaces them.

**spe/evals/harness/r04-workflow.js**

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4 eval. Configs B and C2 on 50 tickets, 5 trials per cell, grade.py label checks, Opus tone judge, $40 cap.',
  phases: [
    { title: 'Preflight' },
    { title: 'Setup' },
    { title: 'Trials' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Extra trials' },
    { title: 'Peek scan' },
    { title: 'Metrics' },
    { title: 'Failure analysis' },
    { title: 'Critic' },
    { title: 'Record' },
  ],
};

// ---------- Constants ----------
const ROUND = 4;
const RR = `r${String(ROUND).padStart(2, '0')}`;
const A = typeof args === 'object' && args ? args : {};

const CONFIG_IDS = ['B', 'C2'];
const EXPECTED_TOOLS = { B: 6, C2: 4 }; // C2 = 3 tools plus check_status
const PROMPT_LINES = 12;
const TICKET_COUNT = 50;
const BASE_TRIALS = A.dryRun ? (A.dryRunTrials ?? 2) : 5;
const EXTRA_PER_SPLIT = A.dryRun ? 0 : (A.extraPerSplitCell ?? 5);
const EXTRA_TOTAL_CAP = A.dryRun ? 0 : (A.extraTotalCap ?? 60);
const CAP_USD = 40;
const CHUNK = A.concurrency ?? 10;
const GRADE_BATCH = 50;
const FAILURE_LIST_CAP = 150;

// Estimates per call in USD. The dry run replaces these through args.estUsd.
const EST = Object.assign(
  { preflight: 0.10, setup: 0.20, trial: 0.04, grade: 0.15, judge: 0.12, scan: 0.30, analysis: 0.80, critic: 0.50, record: 0.20 },
  A.estUsd || {}
);

const TRIAL_MODEL = A.trialModel;
const HARNESS_MODEL = 'opus';
const JUDGE_MODEL = 'opus';
const RUN_DIR = `spe/evals/runs/${RR}${A.dryRun ? '-dry' : ''}`;
const FORBIDDEN = ['spe/evals/graders', 'answers.json', 'spe/predictions', 'spe/plans', 'spe/prediction-log.md', 'spe/failures.md'];

if (!TRIAL_MODEL) throw new Error('args.trialModel is required. Pass the model that r03-workflow.js used.');
if (!A.transcriptGlob) throw new Error('args.transcriptGlob is required for the peek scan.');

// ---------- Spend ledger ----------
let spentEst = 0;
const skips = [];
const haltReasons = [];
const TAIL = EST.scan + EST.analysis + EST.critic + EST.record;

function reserve(kind, what, keepTail = true) {
  const cost = EST[kind];
  const limit = keepTail ? CAP_USD - TAIL : CAP_USD;
  if (spentEst + cost > limit) {
    skips.push({ kind, what, estUsd: cost, spentEstAtSkip: +spentEst.toFixed(2) });
    log(`SKIP ${kind} ${what}: would cross the $${CAP_USD} cap (spent est $${spentEst.toFixed(2)})`);
    return false;
  }
  spentEst += cost;
  return true;
}

async function call(kind, what, prompt, opts, keepTail = true) {
  if (!reserve(kind, what, keepTail)) return { skipped: true };
  try {
    return { value: await agent(prompt, opts) };
  } catch (e) {
    const msg = String((e && e.message) || e);
    log(`ERROR ${what}: ${msg}`);
    return { error: msg };
  }
}

async function inChunks(items, size, fn) {
  const out = [];
  for (let i = 0; i < items.length; i += size) {
    const part = items.slice(i, i + size);
    const res = await parallel(part.map((x) => () => fn(x)));
    out.push(...res);
  }
  return out;
}

function groupByCell(trials) {
  const m = new Map();
  for (const t of trials) {
    const k = `${t.config}:${t.ticket}`;
    if (!m.has(k)) m.set(k, []);
    m.get(k).push(t);
  }
  return m;
}

// ---------- Schemas ----------
const preSchema = {
  type: 'object',
  required: ['selftest_ok', 'prediction_committed', 'tree_clean', 'notes'],
  properties: {
    selftest_ok: { type: 'boolean' },
    prediction_committed: { type: 'boolean' },
    tree_clean: { type: 'boolean' },
    notes: { type: 'string' },
  },
};

const setupSchema = {
  type: 'object',
  required: ['configs', 'tickets'],
  properties: {
    configs: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'system_prompt', 'tools'],
        properties: {
          id: { type: 'string' },
          system_prompt: { type: 'string' },
          tools: {
            type: 'array',
            items: {
              type: 'object',
              required: ['name', 'description'],
              properties: { name: { type: 'string' }, description: { type: 'string' }, parameters: { type: 'string' } },
            },
          },
        },
      },
    },
    tickets: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'subject', 'body'],
        properties: {
          id: { type: 'string' },
          subject: { type: 'string' },
          body: { type: 'string' },
          customer: { type: 'string' },
          fixtures: { type: 'string' },
        },
      },
    },
  },
};

const trialSchema = {
  type: 'object',
  required: ['label', 'reply', 'tool_calls'],
  properties: {
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tool_calls: {
      type: 'array',
      items: { type: 'object', required: ['name'], properties: { name: { type: 'string' }, args: { type: 'string' } } },
    },
  },
};

const gradeSchema = {
  type: 'object',
  required: ['exit_code', 'results', 'stderr_tail'],
  properties: {
    exit_code: { type: 'integer' },
    stderr_tail: { type: 'string' },
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'category_ok', 'priority_ok'],
        properties: { trial_id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } },
      },
    },
  },
};

const judgeSchema = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['key', 'tone_pass', 'score', 'reason'],
        properties: { key: { type: 'string' }, tone_pass: { type: 'boolean' }, score: { type: 'number' }, reason: { type: 'string' } },
      },
    },
  },
};

const scanSchema = {
  type: 'object',
  required: ['trial_transcripts_found', 'with_tool_calls'],
  properties: {
    trial_transcripts_found: { type: 'integer' },
    with_tool_calls: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'tools', 'paths'],
        properties: {
          trial_id: { type: 'string' },
          tools: { type: 'array', items: { type: 'string' } },
          paths: { type: 'array', items: { type: 'string' } },
        },
      },
    },
  },
};

const analysisSchema = {
  type: 'object',
  required: ['types'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'what', 'how_to_spot', 'seen_in', 'existing_id', 'proposed_fix'],
        properties: {
          name: { type: 'string' },
          kind: { type: 'string' },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          existing_id: { type: 'string' },
          proposed_fix: { type: 'string' },
        },
      },
    },
  },
};

const criticSchema = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['what', 'where', 'severity'],
        properties: { what: { type: 'string' }, where: { type: 'string' }, severity: { type: 'string' } },
      },
    },
  },
};

const recordSchema = {
  type: 'object',
  required: ['written'],
  properties: { written: { type: 'array', items: { type: 'string' } } },
};

// ---------- Preflight ----------
phase('Preflight');
const pre = await call('preflight', 'preflight', [
  'Run these commands from the repository root and report the results. Do not edit any file.',
  '1. `python3 -I spe/evals/graders/grade.py --selftest`. selftest_ok is true only if the exit code is 0.',
  `2. \`git log -1 --format=%H -- spe/predictions/${RR}.yaml spe/plans/${RR}.md\`. prediction_committed is true only if it prints a commit hash.`,
  `3. \`git status --porcelain -- spe/predictions/${RR}.yaml spe/plans/${RR}.md spe/evals/graders spe/evals/tasks\`. tree_clean is true only if the output is empty.`,
  'Put any command output that explains a false value in notes.',
].join('\n'), { label: `${RR}-preflight`, phase: 'Preflight', model: HARNESS_MODEL, schema: preSchema });

if (!pre.value || !pre.value.selftest_ok || !pre.value.prediction_committed || !pre.value.tree_clean) {
  throw new Error(`Preflight failed. ${JSON.stringify(pre.value || pre)}`);
}

// ---------- Setup ----------
phase('Setup');
const setupRes = await call('setup', 'setup', [
  'Read these files: spe/evals/configs/B.md, spe/evals/configs/C2.md, spe/evals/tasks/tickets.json.',
  'Do not open spe/evals/tasks/answers.json. Do not open anything under spe/evals/graders, spe/predictions, or spe/plans.',
  'For each config, return its id (B or C2), its system prompt verbatim, and its tool list (name, description, parameters as written).',
  'For each ticket, return id, subject, body, customer, and fixtures verbatim.',
  'Do not summarize, reorder, or fix anything.',
].join('\n'), { label: `${RR}-setup`, phase: 'Setup', model: HARNESS_MODEL, schema: setupSchema });

if (!setupRes.value) throw new Error(`Setup failed. ${setupRes.error || 'skipped by cap'}`);
const setup = setupRes.value;

const cfgById = {};
for (const c of setup.configs) cfgById[c.id] = c;
for (const id of CONFIG_IDS) {
  const c = cfgById[id];
  if (!c) throw new Error(`Setup check: config ${id} missing`);
  const lines = c.system_prompt.trim().split('\n').length;
  if (lines !== PROMPT_LINES) throw new Error(`Setup check: config ${id} prompt has ${lines} lines, expected ${PROMPT_LINES}`);
  if (c.tools.length !== EXPECTED_TOOLS[id]) throw new Error(`Setup check: config ${id} has ${c.tools.length} tools, expected ${EXPECTED_TOOLS[id]}`);
}
if (!cfgById.C2.tools.some((t) => t.name === 'check_status')) throw new Error('Setup check: C2 has no check_status tool');
if (cfgById.B.system_prompt.trim() !== cfgById.C2.system_prompt.trim()) {
  log('WARN setup: B and C2 prompts differ. The plan changes only the tools between them.');
  haltReasons.push('B and C2 system prompts differ, so more than one thing changed between configs');
}
if (setup.tickets.length !== TICKET_COUNT) throw new Error(`Setup check: ${setup.tickets.length} tickets, expected ${TICKET_COUNT}`);
const ticketById = {};
for (const t of setup.tickets) {
  if (ticketById[t.id]) throw new Error(`Setup check: duplicate ticket id ${t.id}`);
  ticketById[t.id] = t;
}

// ---------- Cells and projected spend ----------
const cells = [];
if (A.dryRun) {
  const [t0, t1] = setup.tickets;
  cells.push([CONFIG_IDS[0], t0.id], [CONFIG_IDS[1], t0.id], [CONFIG_IDS[1], t1.id]);
} else {
  for (const t of setup.tickets) for (const c of CONFIG_IDS) cells.push([c, t.id]);
}

const nBase = cells.length * BASE_TRIALS;
const projected = spentEst + nBase * EST.trial + Math.ceil(nBase / GRADE_BATCH) * EST.grade + cells.length * EST.judge + TAIL;
log(`Round ${ROUND}: ${cells.length} cells, ${nBase} base trials, projected base spend est $${projected.toFixed(2)} of $${CAP_USD}`);
if (projected > CAP_USD) throw new Error(`Projected base spend $${projected.toFixed(2)} exceeds the $${CAP_USD} cap. Halting before any trial.`);

// ---------- Trials ----------
function trialPrompt(cfg, t, trialId) {
  const tools = cfg.tools
    .map((x) => `- ${x.name}: ${x.description}${x.parameters ? ` Parameters: ${x.parameters}` : ''}`)
    .join('\n');
  return [
    `TRIAL_ID: ${trialId}`,
    '',
    'You are the support agent described below. Work only from this message.',
    'Do not read, search, or open any file. Do not run any command. Do not use any of your own tools.',
    'To use one of the support tools listed below, add the call to tool_calls. Results for this ticket are in the FIXTURES block.',
    '',
    '## System prompt',
    cfg.system_prompt,
    '',
    '## Support tools',
    tools,
    '',
    '## Ticket',
    `id: ${t.id}`,
    `customer: ${t.customer || ''}`,
    `subject: ${t.subject}`,
    '',
    t.body,
    '',
    '## FIXTURES',
    t.fixtures || '(none)',
    '',
    'Return the label you would set (category and priority), the reply you would send, and the tool calls you made in order.',
  ].join('\n');
}

function codeChecks(t) {
  if (t.status !== 'ok') return t;
  const allowed = new Set(cfgById[t.config].tools.map((x) => x.name));
  t.invalid_tools = (t.out.tool_calls || []).map((x) => x.name).filter((n) => !allowed.has(n));
  const blob = JSON.stringify(t.out);
  const hits = FORBIDDEN.filter((p) => blob.includes(p));
  if (hits.length) {
    t.void = true;
    t.void_reason = `output mentions ${hits.join(', ')}`;
  }
  return t;
}

async function runTrial(job) {
  const r = await call('trial', job.id, trialPrompt(cfgById[job.config], ticketById[job.ticket], job.id), {
    label: job.id,
    phase: job.phase,
    model: TRIAL_MODEL,
    schema: trialSchema,
  });
  const t = { ...job, void: false, invalid_tools: [] };
  if (r.skipped) t.status = 'skipped';
  else if (r.error) Object.assign(t, { status: 'error', error: r.error });
  else Object.assign(t, { status: 'ok', out: r.value });
  return codeChecks(t);
}

phase('Trials');
// Trial index is the outer loop, so a cap hit removes the last trial index across all cells evenly.
const baseJobs = [];
for (let n = 1; n <= BASE_TRIALS; n++) {
  for (const [c, tk] of cells) baseJobs.push({ id: `${RR}-${c}-${tk}-t${n}`, config: c, ticket: tk, n, extra: false, phase: 'Trials' });
}
const baseTrials = await inChunks(baseJobs, CHUNK, runTrial);
const allTrials = [...baseTrials];

const baseSkipped = baseTrials.filter((t) => t.status === 'skipped').length;
const baseErrors = baseTrials.filter((t) => t.status === 'error').length;
log(`Trials: ${baseTrials.length} jobs, ${baseSkipped} skipped by cap, ${baseErrors} errors`);
if (baseSkipped) haltReasons.push(`budget cap reached: ${baseSkipped} base trials skipped`);

// ---------- Grade ----------
async function gradeBatch(batch, name, phaseTitle) {
  const file = `${RUN_DIR}/trials-${name}.jsonl`;
  const lines = batch
    .map((t) => JSON.stringify({ trial_id: t.id, config: t.config, ticket: t.ticket, label: t.out.label, reply: t.out.reply, tool_calls: t.out.tool_calls }))
    .join('\n');
  const r = await call('grade', file, [
    `Write the JSON lines between the markers to ${file}, byte for byte. Create the folder if it does not exist.`,
    `Then run: python3 -I spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --trials ${file} --json`,
    'Do not edit grade.py or answers.json. Do not grade anything yourself.',
    'Return the exit code, the last 20 lines of stderr, and the per-trial results exactly as grade.py printed them.',
    '<<<BEGIN',
    lines,
    'END>>>',
  ].join('\n'), { label: `${RR}-grade-${name}`, phase: phaseTitle, model: HARNESS_MODEL, schema: gradeSchema });

  if (!r.value) { haltReasons.push(`grade batch ${name} did not run: ${r.error || 'skipped by cap'}`); return false; }
  const v = r.value;
  if (v.exit_code !== 0) { haltReasons.push(`grade.py exited ${v.exit_code} on ${file}: ${v.stderr_tail}`); return false; }
  const byId = new Map();
  for (const g of v.results) {
    if (byId.has(g.trial_id)) { haltReasons.push(`grade.py returned ${g.trial_id} twice in ${file}`); return false; }
    byId.set(g.trial_id, g);
  }
  if (byId.size !== batch.length) { haltReasons.push(`grade.py returned ${byId.size} results for ${batch.length} trials in ${file}`); return false; }
  for (const t of batch) {
    const g = byId.get(t.id);
    if (!g) { haltReasons.push(`grade.py result missing for ${t.id}`); return false; }
    t.grade = { category_ok: g.category_ok, priority_ok: g.priority_ok };
  }
  return true;
}

async function gradeAll(trials, tag, phaseTitle) {
  const ok = trials.filter((t) => t.status === 'ok');
  const batches = [];
  for (let i = 0; i < ok.length; i += GRADE_BATCH) batches.push(ok.slice(i, i + GRADE_BATCH));
  const res = await inChunks(batches.map((b, i) => ({ b, i })), CHUNK, ({ b, i }) => gradeBatch(b, `${tag}-${i + 1}`, phaseTitle));
  return res.every(Boolean);
}

phase('Grade');
const graderOk = await gradeAll(baseTrials, 'base', 'Grade');
if (!graderOk) log('HALT: the grader is broken or incomplete. Skipping judge and extra trials.');

// ---------- Judge ----------
async function judgeCell(cellTrials, phaseTitle) {
  const t0 = cellTrials[0];
  const tk = ticketById[t0.ticket];
  // Keys hide the config and trial id from the judge.
  const keyed = cellTrials.map((t, i) => ({ key: `R${i + 1}`, t }));
  const prompt = [
    'Read spe/evals/graders/judge.md and apply its rubric to each reply below.',
    'Judge tone only. Do not judge whether the label is correct.',
    'Judge each reply on its own. Do not compare replies to each other.',
    'Return exactly one score per key.',
    '',
    '## Ticket',
    `subject: ${tk.subject}`,
    '',
    tk.body,
    '',
    '## Replies',
    ...keyed.map(({ key, t }) => `### ${key}\n${t.out.reply}`),
  ].join('\n');
  const r = await call('judge', `judge ${t0.config}:${t0.ticket}${t0.extra ? ' extra' : ''}`, prompt, {
    label: `${RR}-judge-${t0.config}-${t0.ticket}${t0.extra ? '-x' : ''}`,
    phase: phaseTitle,
    model: JUDGE_MODEL,
    schema: judgeSchema,
  });
  if (!r.value) return;
  const byKey = new Map(r.value.scores.map((s) => [s.key, s]));
  for (const { key, t } of keyed) {
    const s = byKey.get(key);
    if (s && typeof s.tone_pass === 'boolean') Object.assign(t, { tone_pass: s.tone_pass, tone_score: s.score, tone_reason: s.reason });
    else log(`judge gave no score for ${t.id}`);
  }
}

async function judgeAll(trials, phaseTitle) {
  const judgeable = trials.filter((t) => t.status === 'ok' && !t.void);
  const groups = [...groupByCell(judgeable).values()];
  await inChunks(groups, CHUNK, (g) => judgeCell(g, phaseTitle));
}

if (graderOk) {
  phase('Judge');
  await judgeAll(baseTrials, 'Judge');
}

// ---------- Extra trials for split cells ----------
const labelOk = (t) => t.grade && t.grade.category_ok && t.grade.priority_ok;
const splitCells = [];
if (graderOk && EXTRA_PER_SPLIT > 0) {
  phase('Extra trials');
  for (const [k, ts] of groupByCell(baseTrials.filter((t) => t.grade && !t.void))) {
    const pass = ts.filter(labelOk).length;
    if (pass > 0 && pass < ts.length) splitCells.push({ cell: k, pass, n: ts.length });
  }
  log(`Split cells: ${splitCells.length}`);

  const extraJobs = [];
  for (let e = 1; e <= EXTRA_PER_SPLIT; e++) {
    for (const s of splitCells) {
      if (extraJobs.length >= EXTRA_TOTAL_CAP) break;
      const [c, tk] = s.cell.split(':');
      const n = BASE_TRIALS + e;
      extraJobs.push({ id: `${RR}-${c}-${tk}-t${n}`, config: c, ticket: tk, n, extra: true, phase: 'Extra trials' });
    }
  }
  if (splitCells.length * EXTRA_PER_SPLIT > EXTRA_TOTAL_CAP) {
    log(`Extra trials capped at ${EXTRA_TOTAL_CAP} (wanted ${splitCells.length * EXTRA_PER_SPLIT})`);
  }

  const extraTrials = await inChunks(extraJobs, CHUNK, runTrial);
  allTrials.push(...extraTrials);
  const extraGraded = await gradeAll(extraTrials, 'extra', 'Extra trials');
  if (extraGraded) await judgeAll(extraTrials, 'Extra trials');
}

// ---------- Peek scan ----------
phase('Peek scan');
const ranTrials = allTrials.filter((t) => t.status === 'ok' || t.status === 'error');
const scan = await call('scan', 'peek scan', [
  `Search the subagent transcripts that match ${A.transcriptGlob}.`,
  `A trial transcript is one whose first user message starts with "TRIAL_ID: ${RR}-".`,
  'Count the trial transcripts you find.',
  'For every trial transcript in which the assistant made any tool call, return its TRIAL_ID, the tool names, and every path or search pattern those calls used.',
  'Do not edit any file.',
].join('\n'), { label: `${RR}-peek-scan`, phase: 'Peek scan', model: HARNESS_MODEL, schema: scanSchema }, false);

const flaggedToolUse = [];
const byTrialId = new Map(allTrials.map((t) => [t.id, t]));
if (!scan.value) {
  haltReasons.push(`peek scan did not run: ${scan.error || 'skipped by cap'}`);
} else {
  if (scan.value.trial_transcripts_found < ranTrials.length) {
    haltReasons.push(`peek scan found ${scan.value.trial_transcripts_found} trial transcripts for ${ranTrials.length} trials run`);
  }
  for (const hit of scan.value.with_tool_calls) {
    const t = byTrialId.get(hit.trial_id);
    if (!t) continue;
    const peeked = hit.paths.filter((p) => FORBIDDEN.some((f) => p.includes(f)));
    if (peeked.length) {
      t.void = true;
      t.void_reason = `peeked at ${peeked.join(', ')}`;
      if (peeked.some((p) => p.includes('answers.json'))) haltReasons.push(`answer key read by ${t.id}`);
    } else {
      flaggedToolUse.push({ trial_id: t.id, tools: hit.tools, paths: hit.paths });
    }
  }
}
const voids = allTrials.filter((t) => t.void).map((t) => ({ trial_id: t.id, reason: t.void_reason }));
log(`Voided ${voids.length} trials. Flagged ${flaggedToolUse.length} for tool use without peeking.`);

// ---------- Metrics ----------
phase('Metrics');
function metrics(trials) {
  const out = {};
  for (const c of CONFIG_IDS) {
    const ts = trials.filter((t) => t.config === c && t.status === 'ok' && !t.void && t.grade);
    const n = ts.length;
    const rate = (f) => (n ? +(ts.filter(f).length / n).toFixed(3) : null);
    const judged = ts.filter((t) => typeof t.tone_pass === 'boolean');
    out[c] = {
      n,
      category_acc: rate((t) => t.grade.category_ok),
      priority_acc: rate((t) => t.grade.priority_ok),
      label_acc: rate(labelOk),
      tone_pass_rate: judged.length ? +(judged.filter((t) => t.tone_pass).length / judged.length).toFixed(3) : null,
      tone_n: judged.length,
      invalid_tool_call_rate: rate((t) => t.invalid_tools.length > 0),
      check_status_use_rate: c === 'C2' ? rate((t) => t.out.tool_calls.some((x) => x.name === 'check_status')) : null,
      mean_tool_calls: n ? +(ts.reduce((s, t) => s + t.out.tool_calls.length, 0) / n).toFixed(2) : null,
    };
  }
  return out;
}
const metricsBase = metrics(allTrials.filter((t) => !t.extra));
const metricsWithExtras = metrics(allTrials);
log(`Base metrics: ${JSON.stringify(metricsBase)}`);

const cellCoverage = [];
for (const [k, ts] of groupByCell(allTrials.filter((t) => !t.extra))) {
  const graded = ts.filter((t) => t.grade && !t.void).length;
  if (graded < BASE_TRIALS) cellCoverage.push({ cell: k, graded, expected: BASE_TRIALS });
}

// ---------- Failure analysis ----------
phase('Failure analysis');
const failures = allTrials
  .filter((t) => t.status === 'ok' && !t.void && t.grade && (!labelOk(t) || t.tone_pass === false))
  .map((t) => ({
    trial_id: t.id,
    config: t.config,
    ticket: t.ticket,
    label: t.out.label,
    category_ok: t.grade.category_ok,
    priority_ok: t.grade.priority_ok,
    tone_pass: t.tone_pass ?? null,
    tone_reason: t.tone_reason || '',
    tools: t.out.tool_calls.map((x) => x.name),
  }));
if (failures.length > FAILURE_LIST_CAP) log(`Failure list truncated from ${failures.length} to ${FAILURE_LIST_CAP} for analysis`);

const analysis = await call('analysis', 'failure analysis', [
  'Read spe/failures.md for the existing F-numbered failure types.',
  `You may read spe/evals/tasks/answers.json, spe/evals/configs/, and the trial files in ${RUN_DIR}.`,
  'Group the failed trials below into failure types. Reuse an existing F-number in existing_id when one fits. Use an empty string when none fits.',
  'Separate failures caused by the config from failures that look like grader or answer-key errors. Set kind to "grader" for the second group.',
  'Do not edit any file.',
  '',
  JSON.stringify(failures.slice(0, FAILURE_LIST_CAP)),
].join('\n'), { label: `${RR}-failure-analysis`, phase: 'Failure analysis', model: HARNESS_MODEL, schema: analysisSchema }, false);

// ---------- Critic ----------
phase('Critic');
const summary = {
  round: ROUND,
  dryRun: !!A.dryRun,
  trialModel: TRIAL_MODEL,
  baseTrialsPerCell: BASE_TRIALS,
  cells: cells.length,
  metricsBase,
  metricsWithExtras,
  splitCells,
  cellCoverage,
  skips,
  voids,
  flaggedToolUse,
  baseErrors,
  graderOk,
  spentEstUsd: +spentEst.toFixed(2),
  capUsd: CAP_USD,
  haltReasons,
};

const critic = await call('critic', 'completeness critic', [
  `Read spe/predictions/${RR}.yaml and spe/plans/${RR}.md. Compare them to the run summary below.`,
  'List every gap. Check for these gaps:',
  '- A predicted metric with no measured number.',
  `- A cell with fewer than ${BASE_TRIALS} graded base trials.`,
  '- A judge coverage gap, a skip, or a void.',
  '- A plan step that this run did not do.',
  'Do not compute verdicts. Do not edit any file.',
  '',
  JSON.stringify(summary),
].join('\n'), { label: `${RR}-critic`, phase: 'Critic', model: HARNESS_MODEL, schema: criticSchema }, false);

// ---------- Record ----------
phase('Record');
const perTrial = allTrials.map((t) => ({
  trial_id: t.id,
  config: t.config,
  ticket: t.ticket,
  n: t.n,
  extra: t.extra,
  status: t.status,
  void: t.void,
  category_ok: t.grade ? t.grade.category_ok : null,
  priority_ok: t.grade ? t.grade.priority_ok : null,
  tone_pass: t.tone_pass ?? null,
  tone_score: t.tone_score ?? null,
  invalid_tools: t.invalid_tools,
}));
const result = {
  ...summary,
  halted: haltReasons.length > 0,
  failureAnalysis: analysis.value || { error: analysis.error || 'skipped by cap' },
  critic: critic.value || { error: critic.error || 'skipped by cap' },
};

const rec = await call('record', 'record', [
  `Write the JSON between the first pair of markers to ${RUN_DIR}/results.json, pretty-printed.`,
  `Write the JSON lines between the second pair of markers to ${RUN_DIR}/per-trial.jsonl, byte for byte.`,
  'Do not edit any other file. Do not commit.',
  '<<<RESULTS',
  JSON.stringify(result),
  'RESULTS>>>',
  '<<<TRIALS',
  perTrial.map((x) => JSON.stringify(x)).join('\n'),
  'TRIALS>>>',
].join('\n'), { label: `${RR}-record`, phase: 'Record', model: HARNESS_MODEL, schema: recordSchema }, false);
if (!rec.value) log(`Record failed: ${rec.error || 'skipped by cap'}. The returned result is the only copy.`);

log(`Done. Spend est $${spentEst.toFixed(2)} of $${CAP_USD}. Halt reasons: ${haltReasons.length ? haltReasons.join(' | ') : 'none'}`);
return result;
